import functools
from typing import Any, Dict
import inspect
from fastapi.dependencies.utils import get_typed_signature

class A:
    pass

def original(a: 'A'):
    return a

# We want to simulate the wrapped function being in a different module.
# We can do this by creating a function with different globals.
def create_wrapped():
    # This function will have its own globals (the globals of this function's module)
    # But we want to wrap 'original' which is in the global scope of this script.

    @functools.wraps(original)
    def wrapped(a):
        return original(a)
    return wrapped

def test_repro():
    wrapped = create_wrapped()
    print(f"Wrapped globals: {wrapped.__globals__}")
    print(f"Original globals: {original.__globals__}")

    try:
        sig = get_typed_signature(wrapped)
        print("Success!")
        print(f"Annotation: {sig.parameters['a'].annotation}")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_repro()
