import functools
from typing import ForwardRef, Any, Dict
import inspect
from fastapi.dependencies.utils import get_typed_signature, evaluate_forwardref

# Simulate two different modules
module_a_globals = {}
class MyModel:
    pass
module_a_globals['MyModel'] = MyModel

def original_func(a: "MyModel"):
    return a
original_func.__globals__ = module_a_globals

module_b_globals = {}
@functools.wraps(original_func)
def wrapper_func(a: "MyModel"):
    return original_func(a)
wrapper_func.__globals__ = module_b_globals

print(f"Original globals: {original_func.__globals__}")
print(f"Wrapper globals: {wrapper_func.__globals__}")

try:
    sig = get_typed_signature(wrapper_func)
    print("Successfully got typed signature")
    print(sig)
