from rich.highlighter import ReprHighlighter
from rich.text import Text

def test_url_tilde():
    highlighter = ReprHighlighter()
    text = Text("Check this URL: https://example.com/~user")
    highlighter.highlight(text)

    # The URL should be highlighted. 
    # ReprHighlighter uses base_style = "repr."
    # The group name is "url", so the style should be "repr.url"

    found_url = False
    for span in text.spans:
        if span.style == "repr.url":
            content = text.plain[span.start:span.end]
            if "https://example.com/~user" in content:
                found_url = True
                break

    if found_url:
        print("SUCCESS: URL with tilde was highlighted")
    else:
        print("FAILURE: URL with tilde was NOT highlighted")
        print(f"Spans: {text.spans}")

if __name__ == "__main__":
    test_url_tilde()

