from fastapi import FastAPI
from pydantic import BaseModel, computed_field
from fastapi.testclient import TestClient
import json

app = FastAPI(separate_input_output_schemas=False)

class Item(BaseModel):
    name: str
    price: float

    @computed_field
    @property
    def total_price(self) -> float:
        return self.price * 1.2

@app.get("/item", response_model=Item)
def read_item():
    return Item(name="Test", price=10.0)

client = TestClient(app)

def test_computed_field_in_openapi():
    response = client.get("/openapi.json")
    openapi_schema = response.json()

    # Find the Item schema
    components = openapi_schema.get("components", {})
    schemas = components.get("schemas", {})
    item_schema = schemas.get("Item")

    assert item_schema is not None, "Item schema not found in OpenAPI"
    properties = item_schema.get("properties", {})

    print(f"Properties found: {list(properties.keys())}")
    assert "total_price" in properties, f"computed field 'total_price' missing from OpenAPI schema when separate_input_output_schemas=False. Properties: {list(properties.keys())}"

if __name__ == "__main__":
    try:
        test_computed_field_in_openapi()
