@app.post("/upload1")
async def upload1(form_data: str = Form(...), file: bytes = File(...)):
    return {"form_data": form_data, "file_len": len(file)}

@app.post("/upload2")
async def upload2(file: bytes = File(...), form_data: str = Form(...)):
    return {"form_data": form_data, "file_len": len(file)}

client = TestClient(app)

def test_form_then_file():
    print("Testing /upload1 (Form then File)...")
    response = client.post(
        "/upload1",
        data={"form_data": "test value"},
        files={"file": ("test.txt", b"test content")}
    )
    print(f"Response: {response.status_code}, Body: {response.json() if response.status_code == 200 else response.text}")
    assert response.status_code == 200

def test_file_then_form():
    print("Testing /upload2 (File then Form)...")
    response = client.post(
        "/upload2",
        data={"form_data": "test value"},
        files={"file": ("test.txt", b"test content")}
    )
    print(f"Response: {response.status_code}, Body: {response.json() if response.status_code == 200 else response.text}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_form_then_file()
        print("test_form_then_file passed!")
        test_file_then_form()
        print("test_file_then_form passed!")
    except Exception as e:
        print(f"Test failed: {e}")

